<script setup lang="ts">
import type {DecorationPage,DecorationLink} from '../../../../api/src/core/decoration-types'
import {decorationHeader} from '../../../../api/src/core/decoration-contract.mjs'
const props=defineProps<{page:DecorationPage;imageUrl:(id:string)=>string;editable?:boolean;miniProgram?:boolean}>()
const emit=defineEmits<{navigate:[target:DecorationLink];selectPage:[]}>()
const header=computed(()=>decorationHeader(props.page))
function go(target:DecorationLink){if(!props.editable&&target)emit('navigate',target)}
</script>
